/* ================= V49: event overview starts with the event, small links under it ================= */
function ovHero(ev){const t=calc(ev.id),full=manages(ev.id),base=`#ev-${ev.id}-`,ph=evPh(ev),st=EVST[ph]||[ev.status];
  return `<section class="ovh">
   <div class="ovh-media">${evCover(ev)}</div>
   <div class="ovh-body"><div class="ovh-tags"><span class="hc-chip">${esc(ev.type)}</span><span class="hc-chip ev-no">${esc(ev.no||'')}</span>${pill(ph,EVST)}</div>
    <h1>${esc(ev.name)}</h1>
    <div class="ovh-meta"><span>${ic('cal',16)}${dfmt(ev.date)} · ${tfmt(ev.start)}–${tfmt(ev.end)}</span><span>${ic('pin',16)}${esc(ev.venue)}${ev.address?', '+esc(ev.address.split(',').slice(-2,-1)[0]||''):''}</span></div>
    <div class="ovh-act">${ev.status!=='void'?`<button class="btn btn-white" data-go="${base}receive">${ic('plus',18)}Receive Moi</button>`:''}<button class="btn btn-glass" data-go="${base}qr">${ic('qr',18)}Event QR</button>${manages(ev.id)&&ev.status!=='void'?`<button class="btn btn-glass" data-act="evEdit" data-id="${ev.id}">${ic('edit',18)}Edit</button>`:''}</div></div>
   <div class="ovh-fig"><span>${full?'Net balance':'Moi received'}</span><strong class="${full&&t.net<0?'neg':''}">${fmt(full?t.net:t.total)}</strong><small>${full?`${fmt(t.total)} Moi − ${fmt(t.expenses)} expenses − ${fmt(t.payouts)} payouts${t.gwFees?` − ${fmt2(t.gwFees)} fees`:''}`:`${t.contributors} contributors so far`}</small></div></section>`}
function ovMini(ev){const b=ev.bookSent,n=ev.notify||{},on=n.wa||n.sms,s=crState(),P_=typeof permOf==='function'?permOf(ev.id):{rep:1},full=manages(ev.id),out=[];
  if(full||P_.rep)out.push(`<button class="ovm" data-act="repOpen" data-id="${ev.id}"><i class="g">${ic('chart',15)}</i><span><b>Event report</b><small>Moi in, money out, balance</small></span></button>`);
  if(full)out.push(b?`<button class="ovm" data-act="bkOpen"><i class="ok">${ic('check',15)}</i><span><b>Moi Book sent</b><small>${b.n} entries · ${new Date(b.at).toLocaleDateString('en-IN',{day:'numeric',month:'short'})}${b.email?' · WhatsApp + email':' · WhatsApp'}</small></span></button>`:`<button class="ovm" data-act="bookMail" data-id="${ev.id}"><i>${ic('bill',15)}</i><span><b>Moi Book</b><small>Sent by itself after ${dfmt(ev.date)}</small></span></button>`);
  if(full)out.push(`<button class="ovm" data-go="#ev-${ev.id}-settings"><i class="${on&&s!=='zero'?(s==='low'?'w':'ok'):'w'}">${ic('msg',15)}</i><span><b>Receipts: ${[n.wa?'WhatsApp':'',n.sms?'SMS':''].filter(Boolean).join(' + ')||'Off'}</b><small>${cr(S.wallet.credits)} credits${on&&s==='zero'?' · paused':on&&s==='low'?' · running low':''}</small></span></button>`);
  if(full&&b)out.push(`<span class="ovm-x"><button class="link small" data-act="bookMail" data-id="${ev.id}">See the email</button>${'·'}<button class="link small" data-act="bookAgain" data-id="${ev.id}">Send Moi Book again</button></span>`);
  return out.length?`<div class="ovm-row">${out.join('')}</div>`:''}
function vOverview(ev){let h=vOverview0(ev);const a=h.indexOf('<section class="hero-card'),z=h.indexOf('</section>',a)+10;if(a<0)return h;h=h.slice(0,a)+ovHero(ev)+ovMini(ev)+h.slice(z);try{const ms=msgStatus(ev);h=h.replace(ms,'')}catch(_){}return h}

/* place the two sample receipts so they never overlap, at any screen width */
function rxFit(){document.querySelectorAll('.ls-art.rxs').forEach(a=>{const W=a.clientWidth,H=a.clientHeight;if(!W||!H)return;const rs=[...a.querySelectorAll('.rx-live')];if(rs.length<2)return;
  const bw=rs.map(r=>r.offsetWidth),bh=rs.map(r=>r.offsetHeight),gap=Math.max(12,W*.05);let z=Math.min(.52,(W*.94-gap)/(bw[0]+bw[1]),(H*.9)/Math.max(...bh));
  const w=bw.map(b=>b*z),h=bh.map(b=>b*z),x0=(W-w[0]-w[1]-gap)/2;
  rs.forEach((r,i)=>{r.style.setProperty('zoom',z.toFixed(4),'important');r.style.setProperty('left',((i?x0+w[0]+gap:x0)/z).toFixed(1)+'px','important');r.style.setProperty('top',(((H-h[i])/2+(i?10:-10))/z).toFixed(1)+'px','important')});a.dataset.fit='1'})}
let _rxq=0;new MutationObserver(()=>{if(_rxq)return;_rxq=requestAnimationFrame(()=>{_rxq=0;try{rxFit()}catch(_){}})}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});addEventListener('resize',()=>{try{rxFit()}catch(_){}});
