function evPh(ev){if(!ev)return 'draft';if(['void','draft','archived'].includes(ev.status)||!ev.date)return ev.status;const n=Date.now(),e=evEndAt(ev);if(n<evStartAt(ev))return 'upcoming';if(n<=e)return 'live';return 'completed'}
