const MCK=[['waU','WhatsApp · utility','Receipts, payment status, reminders, Moi Book','msg',0.35],['waM','WhatsApp · marketing','Invitations, thank-you notes, own messages, campaigns','mail',0.90],['smsT','SMS · transactional','OTP codes, receipts and status by SMS','phone',0.25],['smsP','SMS · promotional','Invitations and offers sent by SMS','bell',0.30]];
function mcRate(k){const pr=P().pricing,c=pr.mcost||{},d=MCK.find(x=>x[0]===k);if(c[k]!=null)return +c[k];if(k==='waU'&&pr.costWa!=null)return +pr.costWa;if(k==='smsT'&&pr.costSms!=null)return +pr.costSms;return d[4]}
/* marketing sends are tagged when they go out; older ones are read from the message log */
let MCAT='';
{const _sm=sendMsg;sendMsg=function(ch,to,text,eid,owner){const r=_sm(ch,to,text,eid,owner);const n=S.notifications[S.notifications.length-1];if(n&&n.text===text)n.cat=MCAT||'util';return r}}
{const _iv=FORMS.invite;FORMS.invite=f=>{MCAT='mkt';const n0=S.msgLog.length?S.msgLog[0].id:'';try{_iv(f)}finally{MCAT=''}if(S.msgLog[0]&&S.msgLog[0].id!==n0){S.msgLog[0].tagged=1;save()}}}
function msgSplit(inr_,wa,sms){let mW=0,mS=0;
  S.notifications.forEach(n=>{if(n.status!=='Sent'||n.cat!=='mkt'||!inr_(n.at))return;n.channel==='WhatsApp'?mW++:mS++});
  (S.msgLog||[]).forEach(l=>{if(l.tagged||!inr_(l.at))return;(l.recips||[]).forEach(r=>{if(r.st!=='sent')return;r.ch==='sms'?mS++:mW++})});
  (P().platLog||[]).forEach(l=>{if(l.kind==='campaign'&&inr_(l.at))mW+=+l.n||0});
  mW=Math.min(mW,wa);mS=Math.min(mS,sms);const n={waU:wa-mW,waM:mW,smsT:sms-mS,smsP:mS},rows=MCK.map(([k,l,d,i])=>({k,l,d,i,n:n[k],rate:mcRate(k),cost:n[k]*mcRate(k)}));return {rows,cost:rows.reduce((s,r)=>s+r.cost,0)}}
function msgCostPanel(r,ed){const R2=v=>'₹'+(Math.round(v*100)/100).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}),N=v=>(+v||0).toLocaleString('en-IN'),M=r.MS;
  return `<div><h3 class="rv-sub">Message cost from the provider</h3><div class="mc-grid">${M.rows.map(x=>`<form class="mc-card" data-mcform="${x.k}"><div class="mc-h"><span class="mc-ic ${x.k}">${ic(x.i,16)}</span><div><b>${x.l}</b><small>${x.d}</small></div></div>
    <div class="mc-n"><span>${N(x.n)} sent</span><b>${R2(x.cost)}</b></div>
    <label class="mc-r"><span>Cost per message (₹)</span><input type="number" step="0.01" min="0" value="${x.rate}" data-mcr ${ed?'':'disabled'} aria-label="${x.l} cost per message"></label>${ed?`<button class="btn btn-ghost btn-sm">Save cost</button>`:''}</form>`).join('')}</div>
    <div class="mc-tot"><span>Total message cost in this period</span><b>${R2(M.cost)}</b></div>
    <p class="small muted">Utility = messages about a Moi already given (receipts, payment status, reminders, Moi Book). Marketing = messages that invite or promote (invitations, thank-you notes, own messages, campaigns). OTP codes count as SMS transactional.${r.est?' Sample accounts are estimated from their usage.':''}</p></div>`}
